<?php require_once __DIR__.'/../includes/functions.php';$items=[];try{$items=db()->query("SELECT * FROM courses WHERE status='published' ORDER BY title")->fetchAll();}catch(Throwable $e){}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Digital Academy | Plateau Digital</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include __DIR__.'/../includes/public_header.php';?><main class="section page-section"><span class="eyebrow">Learn skills for tomorrow</span><h1>Plateau Digital Academy</h1><p>Practical learning, digital skills and training opportunities for individuals and organisations.</p><div class="business-grid"><?php if(!$items):?><div class="empty-state">Our first courses are being prepared. Course enrolment will open soon.</div><?php else:foreach($items as $c):?><article class="business-card"><span class="badge"><?=e(ucfirst($c['delivery']))?></span><h3><?=e($c['title'])?></h3><p><?=e($c['description'])?></p><small><?=e($c['instructor'])?></small></article><?php endforeach;endif;?></div></main><?php include __DIR__.'/../includes/public_footer.php';?></body></html>